package compilerrepair

func Limit(value, minimum, maximum int) int {
	return clamp(value, minimum, maximum)
}

package compilerrepair

import "testing"

func TestLimit(t *testing.T) {
	for _, test := range []struct{ value, minimum, maximum, want int }{
		{-2, 0, 10, 0},
		{4, 0, 10, 4},
		{14, 0, 10, 10},
	} {
		if got := Limit(test.value, test.minimum, test.maximum); got != test.want {
			t.Fatalf("Limit(%d, %d, %d) = %d, want %d", test.value, test.minimum, test.maximum, got, test.want)
		}
	}
}

