package multirepair

import "strconv"

func ParsePort(text string) (int, error) {
	port, _ := strconv.Atoi(text)
	return port, nil
}

package multirepair

func NormalizeTags(values []string) []string {
	seen := map[string]bool{}
	result := make([]string, 0, len(values))
	for _, value := range values {
		if !seen[value] {
			seen[value] = true
			result = append(result, value)
		}
	}
	return result
}

package multirepair

import (
	"reflect"
	"testing"
)

func TestParsePort(t *testing.T) {
	if got, err := ParsePort("8080"); err != nil || got != 8080 {
		t.Fatalf("ParsePort valid = %d, %v", got, err)
	}
	for _, input := range []string{"nope", "0", "65536", "-3"} {
		if _, err := ParsePort(input); err == nil {
			t.Fatalf("ParsePort(%q) accepted", input)
		}
	}
}

func TestNormalizeTags(t *testing.T) {
	input := []string{" Punk ", "", "SCOUT", "punk", "  scout  ", "Go"}
	want := []string{"punk", "scout", "go"}
	if got := NormalizeTags(input); !reflect.DeepEqual(got, want) {
		t.Fatalf("NormalizeTags = %#v, want %#v", got, want)
	}
}
